namespace HRMS.Application.Services;

public sealed class PayrollAccountingService(IHrmsDbContext db, ITenantContext tenant, TimeProvider clock, IPayrollApprovalGuard? approvalGuard = null) : IPayrollAccountingService
{
    public async Task<Result<PagedResult<PayrollGLAccountDto>>> ListAccountsAsync(PagedQuery query, CancellationToken ct = default)
    { if (tenant.TenantId is not Guid id) return Result<PagedResult<PayrollGLAccountDto>>.Unauthorized("No authenticated tenant."); var page = await db.PayrollGLAccounts.AsNoTracking().Where(x => x.TenantId == id).OrderBy(x => x.Code).Select(x => new PayrollGLAccountDto(x.Id, x.Code, x.Name, x.AccountType, x.ExternalCode, x.IsActive)).ToPagedResultAsync(query, ct); return Result<PagedResult<PayrollGLAccountDto>>.Success(page); }
    public async Task<Result<PayrollGLAccountDto>> CreateAccountAsync(PayrollGLAccountRequest request, CancellationToken ct = default)
    { if (tenant.TenantId is not Guid id) return Result<PayrollGLAccountDto>.Unauthorized("No authenticated tenant."); var code = request.Code.Trim().ToUpperInvariant(); if (string.IsNullOrWhiteSpace(code) || string.IsNullOrWhiteSpace(request.Name)) return Result<PayrollGLAccountDto>.Invalid("code", "Account code and name are required."); if (await db.PayrollGLAccounts.AnyAsync(x => x.TenantId == id && x.Code == code, ct)) return Result<PayrollGLAccountDto>.Conflict("GL account code already exists."); var item = new PayrollGLAccount { Id = Guid.NewGuid(), TenantId = id, Code = code, Name = request.Name.Trim(), AccountType = request.AccountType, ExternalCode = request.ExternalCode?.Trim(), IsActive = request.IsActive }; db.PayrollGLAccounts.Add(item); await db.SaveChangesAsync(ct); return Result<PayrollGLAccountDto>.Success(new(item.Id, item.Code, item.Name, item.AccountType, item.ExternalCode, item.IsActive)); }
    public async Task<Result<PayrollGLAccountDto>> UpdateAccountAsync(Guid accountId, PayrollGLAccountRequest request, CancellationToken ct = default)
    { if (tenant.TenantId is not Guid id) return Result<PayrollGLAccountDto>.Unauthorized("No authenticated tenant."); var item = await db.PayrollGLAccounts.FirstOrDefaultAsync(x => x.TenantId == id && x.Id == accountId, ct); if (item is null) return Result<PayrollGLAccountDto>.NotFound("GL account not found."); var code = request.Code.Trim().ToUpperInvariant(); if (await db.PayrollGLAccounts.AnyAsync(x => x.TenantId == id && x.Id != accountId && x.Code == code, ct)) return Result<PayrollGLAccountDto>.Conflict("GL account code already exists."); item.Code = code; item.Name = request.Name.Trim(); item.AccountType = request.AccountType; item.ExternalCode = request.ExternalCode?.Trim(); item.IsActive = request.IsActive; await db.SaveChangesAsync(ct); return Result<PayrollGLAccountDto>.Success(new(item.Id, item.Code, item.Name, item.AccountType, item.ExternalCode, item.IsActive)); }
    public async Task<Result<PagedResult<PayrollAccountingConfigurationDto>>> ListConfigurationsAsync(PagedQuery query, CancellationToken ct = default)
    { if (tenant.TenantId is not Guid id) return Result<PagedResult<PayrollAccountingConfigurationDto>>.Unauthorized("No authenticated tenant."); var source = db.PayrollAccountingConfigurations.AsNoTracking().Include(x => x.Versions).Where(x => x.TenantId == id); var total = await source.CountAsync(ct); var rows = await source.OrderBy(x => x.Code).Skip((query.Page - 1) * query.PageSize).Take(query.PageSize).ToListAsync(ct); var dto = rows.Select(x => new PayrollAccountingConfigurationDto(x.Id, x.Code, x.Name, x.IsActive, x.Versions.OrderByDescending(v => v.EffectiveFrom).Select(v => new PayrollAccountingConfigurationVersionDto(v.Id, v.PayrollAccountingConfigurationId, v.EffectiveFrom, v.EffectiveTo, v.Status, v.AggregationMode, Array.Empty<PayrollGLMappingDto>())).ToList())).ToList(); return Result<PagedResult<PayrollAccountingConfigurationDto>>.Success(new(dto, query.Page, query.PageSize, total)); }
    public async Task<Result<PayrollAccountingConfigurationDto>> CreateConfigurationAsync(PayrollAccountingConfigurationRequest request, CancellationToken ct = default)
    { if (tenant.TenantId is not Guid id) return Result<PayrollAccountingConfigurationDto>.Unauthorized("No authenticated tenant."); var code = request.Code.Trim().ToUpperInvariant(); if (string.IsNullOrWhiteSpace(code) || string.IsNullOrWhiteSpace(request.Name)) return Result<PayrollAccountingConfigurationDto>.Invalid("code", "Configuration code and name are required."); if (await db.PayrollAccountingConfigurations.AnyAsync(x => x.TenantId == id && x.Code == code, ct)) return Result<PayrollAccountingConfigurationDto>.Conflict("Accounting configuration code already exists."); var item = new PayrollAccountingConfiguration { Id = Guid.NewGuid(), TenantId = id, Code = code, Name = request.Name.Trim(), IsActive = request.IsActive }; db.PayrollAccountingConfigurations.Add(item); await db.SaveChangesAsync(ct); return Result<PayrollAccountingConfigurationDto>.Success(new(item.Id, item.Code, item.Name, item.IsActive, Array.Empty<PayrollAccountingConfigurationVersionDto>())); }
    public async Task<Result<PayrollAccountingConfigurationVersionDto>> CreateVersionAsync(Guid configurationId, PayrollAccountingConfigurationVersionRequest request, CancellationToken ct = default)
    { if (tenant.TenantId is not Guid id) return Result<PayrollAccountingConfigurationVersionDto>.Unauthorized("No authenticated tenant."); if (request.EffectiveTo < request.EffectiveFrom) return Result<PayrollAccountingConfigurationVersionDto>.Invalid("effectiveTo", "Effective To cannot be earlier than Effective From."); if (!await db.PayrollAccountingConfigurations.AnyAsync(x => x.TenantId == id && x.Id == configurationId && x.IsActive, ct)) return Result<PayrollAccountingConfigurationVersionDto>.NotFound("Accounting configuration not found."); var overlap = await db.PayrollAccountingConfigurationVersions.AnyAsync(x => x.TenantId == id && x.PayrollAccountingConfigurationId == configurationId && x.Status == PayrollAccountingConfigurationVersionStatus.Active && x.EffectiveFrom <= (request.EffectiveTo ?? DateOnly.MaxValue) && (x.EffectiveTo == null || x.EffectiveTo >= request.EffectiveFrom), ct); if (overlap) return Result<PayrollAccountingConfigurationVersionDto>.Conflict("Accounting configuration versions cannot overlap."); var item = new PayrollAccountingConfigurationVersion { Id = Guid.NewGuid(), TenantId = id, PayrollAccountingConfigurationId = configurationId, EffectiveFrom = request.EffectiveFrom, EffectiveTo = request.EffectiveTo, AggregationMode = request.AggregationMode, Status = PayrollAccountingConfigurationVersionStatus.Active }; db.PayrollAccountingConfigurationVersions.Add(item); await db.SaveChangesAsync(ct); return Result<PayrollAccountingConfigurationVersionDto>.Success(new(item.Id, configurationId, item.EffectiveFrom, item.EffectiveTo, item.Status, item.AggregationMode, Array.Empty<PayrollGLMappingDto>())); }
    public async Task<Result<PayrollGLMappingDto>> CreateMappingAsync(Guid versionId, PayrollGLMappingRequest request, CancellationToken ct = default) => await SaveMappingAsync(null, versionId, request, ct);
    public async Task<Result<PayrollGLMappingDto>> UpdateMappingAsync(Guid mappingId, PayrollGLMappingRequest request, CancellationToken ct = default) => await SaveMappingAsync(mappingId, null, request, ct);
    public async Task<Result<bool>> DeactivateMappingAsync(Guid mappingId, CancellationToken ct = default)
    { if (tenant.TenantId is not Guid id) return Result<bool>.Unauthorized("No authenticated tenant."); var item = await db.PayrollGLMappings.FirstOrDefaultAsync(x => x.TenantId == id && x.Id == mappingId, ct); if (item is null) return Result<bool>.NotFound("GL mapping not found."); item.IsActive = false; await db.SaveChangesAsync(ct); return Result<bool>.Success(true, "GL mapping deactivated."); }
    private async Task<Result<PayrollGLMappingDto>> SaveMappingAsync(Guid? mappingId, Guid? versionId, PayrollGLMappingRequest request, CancellationToken ct)
    { if (tenant.TenantId is not Guid id) return Result<PayrollGLMappingDto>.Unauthorized("No authenticated tenant."); var target = mappingId is Guid mid ? await db.PayrollGLMappings.FirstOrDefaultAsync(x => x.TenantId == id && x.Id == mid, ct) : null; var vId = target?.ConfigurationVersionId ?? versionId; if (vId is not Guid actual || !await db.PayrollAccountingConfigurationVersions.AnyAsync(x => x.TenantId == id && x.Id == actual && x.Status == PayrollAccountingConfigurationVersionStatus.Active, ct)) return Result<PayrollGLMappingDto>.NotFound("Accounting configuration version not found."); var loanMapping = request.MappingType is PayrollGLMappingType.LoanDisbursementReceivable or PayrollGLMappingType.SalaryAdvanceDisbursementReceivable or PayrollGLMappingType.LoanPayrollRecovery or PayrollGLMappingType.LoanInterestRecovery or PayrollGLMappingType.LoanFinalSettlementRecovery or PayrollGLMappingType.ReimbursementExpense or PayrollGLMappingType.ReimbursementPayable or PayrollGLMappingType.TaxableReimbursementExpense or PayrollGLMappingType.ManualReimbursementSettlement or PayrollGLMappingType.PayrollReimbursementSettlement or PayrollGLMappingType.FinalSettlementReimbursement; if (request.SalaryComponentId is null && request.StatutoryType is null && request.MappingType != PayrollGLMappingType.NetPayable && !loanMapping) return Result<PayrollGLMappingDto>.Invalid("source", "A salary component, statutory type, or supported loan source is required."); var accountIds = new[] { request.DebitAccountId, request.CreditAccountId, request.EmployerContributionAccountId }.Where(x => x.HasValue).Select(x => x!.Value).Distinct().ToList(); if (await db.PayrollGLAccounts.AnyAsync(x => x.TenantId == id && accountIds.Contains(x.Id) && !x.IsActive, ct) || await db.PayrollGLAccounts.CountAsync(x => x.TenantId == id && accountIds.Contains(x.Id), ct) != accountIds.Count) return Result<PayrollGLMappingDto>.Conflict("All mapped GL accounts must be active and belong to the tenant."); if (await db.PayrollGLMappings.AnyAsync(x => x.TenantId == id && (!mappingId.HasValue || x.Id != mappingId.Value) && x.ConfigurationVersionId == actual && x.IsActive && x.SalaryComponentId == request.SalaryComponentId && x.StatutoryType == request.StatutoryType && x.MappingType == request.MappingType, ct)) return Result<PayrollGLMappingDto>.Conflict("Duplicate accounting mapping."); target ??= new PayrollGLMapping { Id = Guid.NewGuid(), TenantId = id, ConfigurationVersionId = actual }; target.SalaryComponentId = request.SalaryComponentId; target.StatutoryType = request.StatutoryType; target.MappingType = request.MappingType; target.DebitAccountId = request.DebitAccountId; target.CreditAccountId = request.CreditAccountId; target.EmployerContributionAccountId = request.EmployerContributionAccountId; target.Priority = request.Priority; target.IsActive = request.IsActive; if (mappingId is null) db.PayrollGLMappings.Add(target); await db.SaveChangesAsync(ct); return Result<PayrollGLMappingDto>.Success(new(target.Id, target.ConfigurationVersionId, target.SalaryComponentId, target.StatutoryType, target.MappingType, target.DebitAccountId, target.CreditAccountId, target.EmployerContributionAccountId, target.Priority, target.IsActive)); }
    public async Task<Result<PayrollJournalDto>> GenerateAsync(Guid payrollRunId, CancellationToken ct = default)
    {
        if (tenant.TenantId is not Guid tenantId) return Result<PayrollJournalDto>.Unauthorized("No authenticated tenant.");
        var run = await db.PayrollRuns.Include(x => x.PayrollPeriod).FirstOrDefaultAsync(x => x.TenantId == tenantId && x.Id == payrollRunId, ct);
        if (run?.PayrollPeriod is null) return Result<PayrollJournalDto>.NotFound("Payroll run not found.");
        if (run.Status is not PayrollRunStatus.Approved and not PayrollRunStatus.Finalized) return Result<PayrollJournalDto>.Conflict("Accounting can only be generated for an approved or finalized payroll run.");
        if (await db.PayrollJournalBatches.AnyAsync(x => x.TenantId == tenantId && x.PayrollRunId == payrollRunId && x.Status != PayrollJournalStatus.Cancelled, ct)) return Result<PayrollJournalDto>.Conflict("An active journal already exists for this payroll run.");
        var version = await db.PayrollAccountingConfigurationVersions.Include(x => x.Mappings).Where(x => x.TenantId == tenantId && x.Status == PayrollAccountingConfigurationVersionStatus.Active && x.EffectiveFrom <= run.PayrollPeriod.EndDate && (x.EffectiveTo == null || x.EffectiveTo >= run.PayrollPeriod.EndDate)).OrderByDescending(x => x.EffectiveFrom).FirstOrDefaultAsync(ct);
        if (version is null) return Result<PayrollJournalDto>.Conflict("No active accounting configuration applies to this payroll period.");
        var results = await db.PayrollResults.AsNoTracking().Include(x => x.Components).Where(x => x.TenantId == tenantId && x.PayrollRunId == payrollRunId && x.IsCurrent && x.Status == PayrollResultStatus.Calculated).ToListAsync(ct);
        if (results.Count == 0) return Result<PayrollJournalDto>.Conflict("No calculated payroll results are available.");
        var accountIds = version.Mappings.SelectMany(x => new[] { x.DebitAccountId, x.CreditAccountId, x.EmployerContributionAccountId }).Where(x => x.HasValue).Select(x => x!.Value).Distinct().ToList();
        var accounts = await db.PayrollGLAccounts.Where(x => x.TenantId == tenantId && accountIds.Contains(x.Id) && x.IsActive).ToDictionaryAsync(x => x.Id, ct);
        var journal = new PayrollJournalBatch { Id = Guid.NewGuid(), TenantId = tenantId, PayrollRunId = payrollRunId, PayrollPeriodId = run.PayrollPeriodId, JournalNumber = $"PJ/{run.PayrollPeriod.PayDate:yyyyMM}/{run.Id:N}/1", JournalDate = run.PayrollPeriod.PayDate, CurrencyCode = results.Select(x => x.CurrencyCode).Distinct().SingleOrDefault() ?? "INR", Status = PayrollJournalStatus.Generated, AccountingConfigurationVersionId = version.Id, GeneratedAtUtc = clock.GetUtcNow().UtcDateTime, GeneratedByUserId = tenant.UserId };
        var lines = new List<PayrollJournalLine>();
        foreach (var result in results)
        {
            foreach (var component in result.Components.Where(x => x.CalculatedAmount != 0))
            {
                var mapping = component.CalculationSource == "LoanRecovery"
                    ? version.Mappings.Where(x => x.IsActive && x.MappingType == PayrollGLMappingType.LoanPayrollRecovery).OrderBy(x => x.Priority).FirstOrDefault()
                    : component.CalculationSource is "TaxableReimbursement" or "NonTaxableReimbursement"
                        ? version.Mappings.Where(x => x.IsActive && x.MappingType == (component.CalculationSource == "TaxableReimbursement" ? PayrollGLMappingType.TaxableReimbursementExpense : PayrollGLMappingType.ReimbursementExpense)).OrderBy(x => x.Priority).FirstOrDefault()
                        : version.Mappings.Where(x => x.IsActive && x.SalaryComponentId == component.SalaryComponentId).OrderBy(x => x.Priority).FirstOrDefault();
                if (mapping is null || mapping.DebitAccountId is null || mapping.CreditAccountId is null || !accounts.ContainsKey(mapping.DebitAccountId.Value) || !accounts.ContainsKey(mapping.CreditAccountId.Value)) return Result<PayrollJournalDto>.Conflict($"MissingGLMapping for component {component.ComponentCode}.");
                var amount = decimal.Round(Math.Abs(component.CalculatedAmount), 2, MidpointRounding.AwayFromZero);
                if (component.CalculationSource == "LoanRecovery")
                {
                    var sourceId = component.LoanInstallmentId ?? component.EmployeeLoanId ?? component.Id;
                    AddLine(lines, accounts[mapping.CreditAccountId.Value], 0, amount, component.ComponentCode, sourceId, component, "LoanRepayment");
                }
                else
                {
                    if (component.IsEarning || component.IsEmployerContribution) AddLine(lines, accounts[mapping.DebitAccountId.Value], amount, 0, component.ComponentCode, component.Id, component, "PayrollResultComponent");
                    if (component.IsDeduction || component.IsEmployerContribution) AddLine(lines, accounts[mapping.CreditAccountId.Value], 0, amount, component.ComponentCode, component.Id, component, "PayrollResultComponent");
                }
            }
            var payable = version.Mappings.Where(x => x.IsActive && x.MappingType == PayrollGLMappingType.NetPayable).OrderBy(x => x.Priority).FirstOrDefault();
            if (payable?.CreditAccountId is not Guid payableId || !accounts.TryGetValue(payableId, out var payableAccount)) return Result<PayrollJournalDto>.Conflict("MissingGLMapping for net salary payable.");
            AddLine(lines, payableAccount, 0, decimal.Round(result.NetPay, 2, MidpointRounding.AwayFromZero), "Net Payable", result.Id, null, "PayrollResult");
        }
        journal.Lines = lines; journal.TotalDebit = lines.Sum(x => x.Debit); journal.TotalCredit = lines.Sum(x => x.Credit); journal.LineCount = lines.Count;
        if (journal.TotalDebit != journal.TotalCredit) return Result<PayrollJournalDto>.Conflict("Generated journal is unbalanced.");
        journal.History.Add(new PayrollJournalHistory { Id = Guid.NewGuid(), TenantId = tenantId, ChangeType = PayrollJournalHistoryChangeType.Generated, ChangedAtUtc = clock.GetUtcNow().UtcDateTime, ActorUserId = tenant.UserId, Message = "Journal generated from persisted payroll results." });
        db.PayrollJournalBatches.Add(journal); await db.SaveChangesAsync(ct); return Result<PayrollJournalDto>.Success(ToDto(journal), "Payroll journal generated.");
    }

    public async Task<Result<PayrollJournalDto>> GenerateFinalSettlementAsync(Guid finalSettlementId, CancellationToken ct = default)
    {
        if (tenant.TenantId is not Guid tenantId) return Result<PayrollJournalDto>.Unauthorized("No authenticated tenant.");
        var settlement = await db.FinalSettlementCases.AsNoTracking().FirstOrDefaultAsync(x => x.TenantId == tenantId && x.Id == finalSettlementId, ct);
        if (settlement is null) return Result<PayrollJournalDto>.NotFound("Final settlement not found.");
        if (settlement.Status != FinalSettlementStatus.Finalized) return Result<PayrollJournalDto>.Conflict("Accounting can only be generated for a finalized final settlement.");
        if (await db.PayrollJournalBatches.AnyAsync(x => x.TenantId == tenantId && x.FinalSettlementCaseId == finalSettlementId && x.Status != PayrollJournalStatus.Cancelled, ct)) return Result<PayrollJournalDto>.Conflict("An active journal already exists for this final settlement.");
        var version = await db.PayrollAccountingConfigurationVersions.Include(x => x.Mappings).Where(x => x.TenantId == tenantId && x.Status == PayrollAccountingConfigurationVersionStatus.Active && x.EffectiveFrom <= settlement.SettlementDate && (x.EffectiveTo == null || x.EffectiveTo >= settlement.SettlementDate)).OrderByDescending(x => x.EffectiveFrom).FirstOrDefaultAsync(ct);
        if (version is null) return Result<PayrollJournalDto>.Conflict("No active accounting configuration applies to this final settlement.");
        var repayments = await db.LoanRepayments.AsNoTracking().Where(x => x.TenantId == tenantId && x.RepaymentType == LoanRepaymentType.FinalSettlement && x.SourceType == "FinalSettlement" && x.Reference == finalSettlementId.ToString() && x.Amount > 0).ToListAsync(ct);
        var reimbursements = await db.ReimbursementSettlements.AsNoTracking().Where(x => x.TenantId == tenantId && x.FinalSettlementId == finalSettlementId && x.SettlementType == ReimbursementSettlementType.FinalSettlement && x.Amount > 0).ToListAsync(ct);
        if (repayments.Count == 0 && reimbursements.Count == 0) return Result<PayrollJournalDto>.Conflict("No finalized loan recovery or reimbursement settlement is available for this final settlement.");
        var finalMapping = version.Mappings.Where(x => x.IsActive && x.MappingType == PayrollGLMappingType.LoanFinalSettlementRecovery).OrderBy(x => x.Priority).FirstOrDefault();
        var reimbursementMapping = version.Mappings.Where(x => x.IsActive && x.MappingType == PayrollGLMappingType.FinalSettlementReimbursement).OrderBy(x => x.Priority).FirstOrDefault();
        if (repayments.Count > 0 && (finalMapping?.DebitAccountId is not Guid || finalMapping.CreditAccountId is not Guid)) return Result<PayrollJournalDto>.Conflict("MissingGLMapping for final settlement loan recovery.");
        if (reimbursements.Count > 0 && (reimbursementMapping?.DebitAccountId is not Guid || reimbursementMapping.CreditAccountId is not Guid)) return Result<PayrollJournalDto>.Conflict("MissingGLMapping for final settlement reimbursement.");
        var settlementAccountId = finalMapping?.DebitAccountId ?? reimbursementMapping!.DebitAccountId!.Value;
        var receivableAccountId = finalMapping?.CreditAccountId;
        var interestMapping = version.Mappings.Where(x => x.IsActive && x.MappingType == PayrollGLMappingType.LoanInterestRecovery).OrderBy(x => x.Priority).FirstOrDefault();
        var accountIds = new[] { finalMapping?.DebitAccountId, finalMapping?.CreditAccountId, reimbursementMapping?.DebitAccountId, reimbursementMapping?.CreditAccountId, interestMapping?.CreditAccountId }.Where(x => x.HasValue).Select(x => x!.Value).Distinct().ToList();
        var accounts = await db.PayrollGLAccounts.Where(x => x.TenantId == tenantId && accountIds.Contains(x.Id) && x.IsActive).ToDictionaryAsync(x => x.Id, ct);
        if (!accounts.ContainsKey(settlementAccountId) || (receivableAccountId is Guid receivable && !accounts.ContainsKey(receivable)) || (reimbursementMapping?.CreditAccountId is Guid reimbursementCredit && !accounts.ContainsKey(reimbursementCredit)) || (interestMapping?.CreditAccountId is Guid interestId && !accounts.ContainsKey(interestId))) return Result<PayrollJournalDto>.Conflict("MissingGLMapping for final settlement source.");
        var journal = new PayrollJournalBatch { Id = Guid.NewGuid(), TenantId = tenantId, FinalSettlementCaseId = finalSettlementId, JournalNumber = $"FSJ/{settlement.SettlementDate:yyyyMM}/{finalSettlementId:N}/1", JournalDate = settlement.SettlementDate, CurrencyCode = settlement.CurrencyCode, Status = PayrollJournalStatus.Generated, AccountingConfigurationVersionId = version.Id, GeneratedAtUtc = clock.GetUtcNow().UtcDateTime, GeneratedByUserId = tenant.UserId };
        foreach (var repayment in repayments)
        {
            var amount = decimal.Round(repayment.Amount, 2, MidpointRounding.AwayFromZero);
            var interest = decimal.Round(Math.Min(repayment.InterestAmount, amount), 2, MidpointRounding.AwayFromZero);
            var principal = decimal.Round(amount - interest, 2, MidpointRounding.AwayFromZero);
            AddLine(journal.Lines, accounts[settlementAccountId], amount, 0, "Final settlement loan recovery", repayment.Id, null, "FinalSettlementLoanRepayment", repayment.EmployeeLoanId, finalSettlementId);
            if (principal > 0) AddLine(journal.Lines, accounts[receivableAccountId!.Value], 0, principal, "Loan principal recovered through final settlement", repayment.Id, null, "FinalSettlementLoanRepayment", repayment.EmployeeLoanId, finalSettlementId);
            if (interest > 0) AddLine(journal.Lines, interestMapping?.CreditAccountId is Guid interestAccountId ? accounts[interestAccountId] : accounts[receivableAccountId!.Value], 0, interest, "Loan interest recovered through final settlement", repayment.Id, null, "FinalSettlementLoanRepayment", repayment.EmployeeLoanId, finalSettlementId);
        }
        foreach (var reimbursement in reimbursements)
        {
            AddLine(journal.Lines, accounts[reimbursementMapping!.DebitAccountId!.Value], reimbursement.Amount, 0, "Final settlement reimbursement", reimbursement.Id, null, "FinalSettlementReimbursement", null, finalSettlementId);
            AddLine(journal.Lines, accounts[reimbursementMapping.CreditAccountId!.Value], 0, reimbursement.Amount, "Reimbursement payable settled through final settlement", reimbursement.Id, null, "FinalSettlementReimbursement", null, finalSettlementId);
        }
        journal.TotalDebit = journal.Lines.Sum(x => x.Debit); journal.TotalCredit = journal.Lines.Sum(x => x.Credit); journal.LineCount = journal.Lines.Count;
        if (journal.TotalDebit != journal.TotalCredit) return Result<PayrollJournalDto>.Conflict("Generated journal is unbalanced.");
        journal.History.Add(new PayrollJournalHistory { Id = Guid.NewGuid(), TenantId = tenantId, ChangeType = PayrollJournalHistoryChangeType.Generated, ChangedAtUtc = clock.GetUtcNow().UtcDateTime, ActorUserId = tenant.UserId, Message = "Journal generated from finalized final settlement loan repayments." });
        db.PayrollJournalBatches.Add(journal); await db.SaveChangesAsync(ct); return Result<PayrollJournalDto>.Success(ToDto(journal), "Final settlement journal generated.");
    }

    public async Task<Result<PayrollJournalDto>> ValidateAsync(Guid journalId, CancellationToken ct = default) => await TransitionAsync(journalId, PayrollJournalStatus.Validated, PayrollJournalHistoryChangeType.Validated, "Payroll journal validated.", PayrollJournalStatus.Generated, ct);
    public async Task<Result<PayrollJournalDto>> ApproveAsync(Guid journalId, CancellationToken ct = default) => await TransitionAsync(journalId, PayrollJournalStatus.Approved, PayrollJournalHistoryChangeType.Approved, "Payroll journal approved.", PayrollJournalStatus.Validated, ct);
    public async Task<Result<PayrollJournalDto>> PostAsync(Guid journalId, CancellationToken ct = default) => await TransitionAsync(journalId, PayrollJournalStatus.Posted, PayrollJournalHistoryChangeType.Posted, "Payroll journal posted within HRMS.", PayrollJournalStatus.Approved, ct);

    public async Task<Result<PayrollJournalDto>> GetAsync(Guid journalId, CancellationToken ct = default)
    {
        if (tenant.TenantId is not Guid tenantId) return Result<PayrollJournalDto>.Unauthorized("No authenticated tenant.");
        var row = await db.PayrollJournalBatches.AsNoTracking().Include(x => x.Lines).FirstOrDefaultAsync(x => x.TenantId == tenantId && x.Id == journalId, ct);
        return row is null ? Result<PayrollJournalDto>.NotFound("Payroll journal not found.") : Result<PayrollJournalDto>.Success(ToDto(row));
    }

    public async Task<Result<PagedResult<PayrollJournalDto>>> ListAsync(PagedQuery query, CancellationToken ct = default)
    {
        if (tenant.TenantId is not Guid tenantId) return Result<PagedResult<PayrollJournalDto>>.Unauthorized("No authenticated tenant.");
        var source = db.PayrollJournalBatches.AsNoTracking().Include(x => x.Lines).Where(x => x.TenantId == tenantId); var total = await source.CountAsync(ct); var rows = await source.OrderByDescending(x => x.CreatedDate).Skip((query.Page - 1) * query.PageSize).Take(query.PageSize).ToListAsync(ct);
        return Result<PagedResult<PayrollJournalDto>>.Success(new PagedResult<PayrollJournalDto>(rows.Select(ToDto).ToList(), query.Page, query.PageSize, total));
    }

    public async Task<Result<PayrollOutputFile>> ExportAsync(Guid journalId, CancellationToken ct = default)
    {
        var row = await GetAsync(journalId, ct); if (!row.Succeeded) return Result<PayrollOutputFile>.Failure(row.Status, row.Message); var j = row.Value!; if (j.Status is not PayrollJournalStatus.Approved and not PayrollJournalStatus.Posted and not PayrollJournalStatus.Exported) return Result<PayrollOutputFile>.Conflict("Only an approved or posted journal can be exported.");
        var sb = new StringBuilder("JournalNumber,JournalDate,AccountCode,AccountName,Description,Debit,Credit,Currency,SourceType,SourceId\r\n"); foreach (var l in j.Lines.OrderBy(x => x.Sequence)) sb.Append(string.Join(',', Csv(j.JournalNumber), j.JournalDate.ToString("yyyy-MM-dd"), Csv(l.AccountCode), Csv(l.AccountName), Csv(l.Description), l.Debit.ToString(CultureInfo.InvariantCulture), l.Credit.ToString(CultureInfo.InvariantCulture), Csv(l.CurrencyCode), Csv(l.SourceType), l.SourceId?.ToString() ?? string.Empty)).Append("\r\n");
        return Result<PayrollOutputFile>.Success(new PayrollOutputFile($"payroll-journal-{j.JournalNumber.Replace('/', '-')}.csv", "text/csv; charset=utf-8", Encoding.UTF8.GetBytes(sb.ToString())));
    }

    private async Task<Result<PayrollJournalDto>> TransitionAsync(Guid id, PayrollJournalStatus next, PayrollJournalHistoryChangeType change, string message, PayrollJournalStatus expected, CancellationToken ct)
    {
        if (tenant.TenantId is not Guid tenantId) return Result<PayrollJournalDto>.Unauthorized("No authenticated tenant."); var row = await db.PayrollJournalBatches.Include(x => x.Lines).FirstOrDefaultAsync(x => x.TenantId == tenantId && x.Id == id, ct); if (row is null) return Result<PayrollJournalDto>.NotFound("Payroll journal not found."); if (row.Status != expected) return Result<PayrollJournalDto>.Conflict($"Invalid journal transition from {row.Status} to {next}."); if (next is PayrollJournalStatus.Approved or PayrollJournalStatus.Posted && row.TotalDebit != row.TotalCredit) return Result<PayrollJournalDto>.Conflict("Unbalanced journals cannot be approved or posted."); if (next is PayrollJournalStatus.Approved or PayrollJournalStatus.Posted) { var guard = await (approvalGuard ?? new PayrollApprovalGuard(db, tenant)).ValidateAsync(row.GeneratedByUserId, next == PayrollJournalStatus.Approved ? "approve" : "post", ct: ct); if (!guard.Succeeded) return Result<PayrollJournalDto>.Failure(guard.Status, guard.Message, guard.Errors); }
        var changedAt = clock.GetUtcNow().UtcDateTime; var update = db.PayrollJournalBatches.Where(x => x.TenantId == tenantId && x.Id == id && x.Status == expected && x.ConcurrencyVersion == row.ConcurrencyVersion);
        var changed = next == PayrollJournalStatus.Approved
            ? await update.ExecuteUpdateAsync(setters => setters.SetProperty(x => x.Status, next).SetProperty(x => x.ApprovedAtUtc, changedAt).SetProperty(x => x.ConcurrencyVersion, x => x.ConcurrencyVersion + 1), ct)
            : next == PayrollJournalStatus.Posted
                ? await update.ExecuteUpdateAsync(setters => setters.SetProperty(x => x.Status, next).SetProperty(x => x.PostedAtUtc, changedAt).SetProperty(x => x.ConcurrencyVersion, x => x.ConcurrencyVersion + 1), ct)
                : await update.ExecuteUpdateAsync(setters => setters.SetProperty(x => x.Status, next).SetProperty(x => x.ConcurrencyVersion, x => x.ConcurrencyVersion + 1), ct);
        if (changed != 1) return Result<PayrollJournalDto>.Conflict("Payroll journal was changed by another operation.");
        db.ClearChangeTracker(); var refreshed = await db.PayrollJournalBatches.Include(x => x.Lines).FirstAsync(x => x.TenantId == tenantId && x.Id == id, ct); db.PayrollJournalHistories.Add(new PayrollJournalHistory { Id = Guid.NewGuid(), TenantId = tenantId, PayrollJournalBatchId = id, ChangeType = change, ChangedAtUtc = changedAt, ActorUserId = tenant.UserId, Message = message }); await db.SaveChangesAsync(ct); return Result<PayrollJournalDto>.Success(ToDto(refreshed), message);
    }

    private static void AddLine(ICollection<PayrollJournalLine> lines, PayrollGLAccount account, decimal debit, decimal credit, string description, Guid sourceId, PayrollResultComponent? component, string sourceType, Guid? loanId = null, Guid? settlementId = null) { var line = new PayrollJournalLine { Id = Guid.NewGuid(), TenantId = account.TenantId, Sequence = lines.Count + 1, PayrollGLAccountId = account.Id, AccountCodeSnapshot = account.Code, AccountNameSnapshot = account.Name, Description = description, Debit = debit, Credit = credit, CurrencyCode = "INR", SourceType = sourceType, SourceId = sourceId, SalaryComponentId = component?.SalaryComponentId }; if (loanId is Guid l) line.Sources.Add(new PayrollJournalLineSource { Id = Guid.NewGuid(), TenantId = account.TenantId, SourceType = "EmployeeLoan", SourceId = l, Amount = debit + credit }); if (settlementId is Guid s) line.Sources.Add(new PayrollJournalLineSource { Id = Guid.NewGuid(), TenantId = account.TenantId, SourceType = "FinalSettlement", SourceId = s, Amount = debit + credit }); lines.Add(line); }
    private static PayrollJournalDto ToDto(PayrollJournalBatch x) => new(x.Id, x.PayrollRunId, x.PayrollPeriodId, x.JournalNumber, x.JournalDate, x.CurrencyCode, x.Status, x.TotalDebit, x.TotalCredit, x.Lines.OrderBy(y => y.Sequence).Select(y => new PayrollJournalLineDto(y.Id, y.Sequence, y.AccountCodeSnapshot, y.AccountNameSnapshot, y.Description, y.Debit, y.Credit, y.CurrencyCode, y.SourceType, y.SourceId)).ToList());
    private static string Csv(string value) => value.Contains(',') || value.Contains('"') || value.Contains('\n') || value.Contains('\r') ? $"\"{value.Replace("\"", "\"\"")}\"" : value;
}
